#!/usr/bin/env python3
"""
Round 139b (culprits-tiles-more), 2 October 2026.

fao_fisheries.py (new): FAO FishStat capture and aquaculture, country by country.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/fao_fisheries.py': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round139b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round139b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
